from pathlib import Path
import os

def broad_search():
    print("=== RealAI Broad Machine Search ===\n")

    # Common locations
    search_paths = [
        Path.home() / "Downloads",
        Path.home() / "Desktop",
        Path.home() / "Documents",
        Path.home() / "OneDrive",
        Path("C:/Users/tsmit"),
        Path.cwd().parent,           # Parent of realai folder
        Path("D:/"),                 # Add other drives if you have them
    ]

    keywords = ["realai", "plugin", "pyautogui", "pytesseract", "solana", "faiss", "lora", "gpu_balancer", "rise", "grpo", "hierarchical"]

    found = []
    for base in search_paths:
        if not base.exists():
            continue
        print(f"Scanning {base} ...")
        try:
            for file in base.rglob("*.py"):
                if any(ign in file.parts for ign in [".venv", "__pycache__", ".git", "node_modules"]):
                    continue
                try:
                    text = file.read_text(errors="ignore").lower()
                    if any(kw in text or kw in file.name.lower() for kw in keywords):
                        found.append(file)
                        print(f"  → Found: {file}")
                except:
                    continue
        except Exception as e:
            print(f"  Error scanning {base}: {e}")

    print(f"\n=== Found {len(found)} potential files ===")
    for f in found[:30]:
        print(f)
    return found

if __name__ == "__main__":
    broad_search()

import requests
from pathlib import Path
from typing import List, Dict

class RealAIFullAutonomous:
    def __init__(self, base_url: str = "http://127.0.0.1:8080/v1"):
        self.base_url = base_url
        self.model = "bartowski/Llama-3.2-3B-Instruct-GGUF:Llama-3.2-3B-Instruct-Q5_K_M.gguf"

    def chat(self, messages: List[Dict], max_tokens: int = 8192):
        try:
            response = requests.post(
                f"{self.base_url}/chat/completions",
                json={"model": self.model, "messages": messages, "temperature": 0.2, "max_tokens": max_tokens},
                timeout=180
            )
            response.raise_for_status()
            return response.json()["choices"][0]["message"]["content"]
        except Exception as e:
            print("Error:", e)
            return None

    def explore_project(self, root: str = ".") -> str:
        """Safely build project structure"""
        ignore = {".venv", "__pycache__", ".git", ".cache", "node_modules", "models"}
        structure = []
        try:
            for path in sorted(Path(root).rglob("*")):
                try:
                    if path.is_file() and not any(ign in path.parts for ign in ignore):
                        structure.append(str(path.relative_to(root)))
                        if len(structure) >= 120:
                            break
                except (OSError, PermissionError):
                    continue  # Skip problematic files/symlinks
        except Exception as e:
            structure.append(f"Error exploring: {e}")
        return "\n".join(structure)

    def improve_file(self, file_path: Path, goal: str):
        try:
            original = file_path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            print(f"❌ Could not read {file_path.name}")
            return

        system = "You are RealAI Agent. Output ONLY the complete improved Python code. No explanations."

        messages = [
            {"role": "system", "content": system},
            {"role": "user", "content": f"File: {file_path.name}\n\n{original}\n\nTask: {goal}"}
        ]

        final = self.chat(messages)
        if final:
            if "```" in final:
                final = final.split("```python")[-1].split("```")[0] if "```python" in final else final.split("```")[-1].split("```")[0]
            try:
                file_path.write_text(final.strip(), encoding="utf-8")
                print(f"✅ Improved: {file_path.name}")
            except Exception as e:
                print(f"❌ Failed to write {file_path.name}: {e}")
        else:
            print(f"❌ No response for {file_path.name}")

def _load_saved_keys(self) -> None:
        """Populate entry fields from the saved config file."""
        config = load_config()
        for provider_id, entry in self._entries.items():
            value = config.get(provider_id, "")
            if value:
                entry.delete(0, tk.END)
                entry.insert(0, value)
        configured = [p for p in PROVIDERS if config.get(p)]
        if configured:
            names = ", ".join(PROVIDERS[p]["label"] for p in configured)
            self._status_var.set(f"Loaded saved keys for: {names}")

    def _save_keys(self) -> None:
        """Write the current entry values to disk and apply them as env vars."""
        config = {pid: entry.get().strip() for pid, entry in self._entries.items()}
        save_config(config)

        # Apply to the current process environment so a server subprocess inherits them.
        for provider_id, key in config.items():
            env_var = PROVIDERS[provider_id]["env_var"]
            if key:
                os.environ[env_var] = key
            else:
                os.environ.pop(env_var, None)

        configured = [p for p, v in config.items() if v]
        if configured:
            names = ", ".join(PROVIDERS[p]["label"] for p in configured)
            self._status_var.set(f"\u2705 Saved keys for: {names}")
        else:
            self._status_var.set("\u2705 Saved (no keys — RealAI runs in placeholder mode).")

    def _clear_keys(self) -> None:
        for entry in self._entries.values():
            entry.delete(0, tk.END)
        self._status_var.set("Keys cleared \u2014 click Save to persist.")

    # ------------------------------------------------------------------
    # Chat functionality
    # ------------------------------------------------------------------

    def _append_to_chat(self, text: str) -> None:
        """Append text to the chat display (safe to call from any thread)."""
        self._chat_display.config(state="normal")
        self._chat_display.insert(tk.END, text + "\n\n")
        self._chat_display.see(tk.END)
        self._chat_display.config(state="disabled")

