class RealAIPluginRecoverer:
    def __init__(self, base_url: str = "http://127.0.0.1:8080/v1"):
        self.base_url = base_url
        self.model = "bartowski/Llama-3.2-3B-Instruct-GGUF:Llama-3.2-3B-Instruct-Q5_K_M.gguf"

    def chat(self, messages: List[Dict]):
        try:
            resp = requests.post(f"{self.base_url}/chat/completions", json={
                "model": self.model, "messages": messages, "temperature": 0.2, "max_tokens": 8192
            }, timeout=180)
            resp.raise_for_status()
            return resp.json()["choices"][0]["message"]["content"]
        except Exception as e:
            print("Error:", e)
            return None

    def recover_plugin(self, file_path: str):
        print(f"\n=== Recovering: {file_path} ===")
        try:
            content = Path(file_path).read_text(encoding="utf-8", errors="ignore")
        except Exception as e:
            print("Could not read file")
            return

        messages = [
            {"role": "system", "content": "You are RealAI Plugin Recovery Specialist. Extract the plugin logic and suggest how to turn it into a clean RealAI plugin."},
            {"role": "user", "content": f"File: {file_path}\n\n{content[:6000]}"}
        ]

        result = self.chat(messages)
        if result:
            print(result[:1200] + "..." if len(result) > 1200 else result)

            # Save analysis
            Path("plugin_analysis.md").write_text(result, encoding="utf-8", errors="ignore")
            print("Analysis saved to plugin_analysis.md")

if __name__ == "__main__":
