    # Focus on the best candidates you found
    candidates = [
        "local_models.py",
        "local_model_cli.py",
        "realai_architect_agent.py",
        "device_utils.py",
        "lambda_core.py",
        "examples_ultimate.py"
    ]

    for f in candidates:
        if Path(f).exists():
            recoverer.recover_plugin(f)

