        )


def run_model_completion(
    agent: AgentDefinition,
    task: str,
    metadata: dict[str, Any],
    config: ExecutionBackendConfig,
) -> dict[str, Any]:
    backend_name = config.name.strip().lower()
    if backend_name == "simulated":
        raise ValueError("Simulated backend does not support direct model completion")
    if backend_name != "openai-compatible":
        raise ValueError(f"Unsupported execution backend: {config.name}")

    return _run_openai_compatible_completion(agent, task, metadata, config)


